import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    p = list(map(int, data[1:n+1]))

    if n < 3:
        print("NO")
        return

    pos = [0] * (n + 1)
    for i, x in enumerate(p):
        pos[x] = i

    max_val = -1
    min_val = float('inf')

    for i in range(n):
        x = p[i]
        if x > max_val:
            max_val = x
        if x < min_val:
            min_val = x

        if i >= 2:
            if max_val < n and min_val > 1:
                print("YES")
                return

    print("NO")

if __name__ == "__main__":
    solve()
